"""The designer's tools (docs/auto_open/PLAN.md §4): a CLI the designer agent runs in its sandbox.

    <python> -m src.rsa_open.tools validate   --workspace <ws> --spec <ws>/work/p.json
    <python> -m src.rsa_open.tools eig        --workspace <ws> --spec <ws>/work/p.json
    <python> -m src.rsa_open.tools link-check --workspace <ws> --spec <ws>/work/p.json
    <python> -m src.rsa_open.tools submit     --workspace <ws> --spec <ws>/work/p.json

**The workspace** (`Workspace`) is one designer session's directory, laid out by the harness
(`src.rsa_open.designer`):
- ``context/``: the design context (`src.rsa_open.design`), with the closed paradigm's reference
  score already computed; read-only to the agent;
- ``inputs/``: the brief, the spec's JSON schema, the link library, the chain's earlier
  paradigms and the timing records (``timing.json``, `src.rsa_open.timing`); read-only;
- ``work/``: the agent's own directory (its specs, ``reports/``, ``tool_log.jsonl`` and
  ``submission.json``).

**The commands:**
- ``validate``: the spec's problems, all at once (`src.rsa_open.paradigm`), the trial units
  against the EIG tool's limit, and the pilot's time estimate against the declared minutes, on a
  random design from the scene space;
- ``eig``: the paradigm's design under the live theories, its bits per dollar and the floor, and
  the time estimate on that design; ``--quick`` scores it with ``QUICK_DRAWS`` draws and
  ``QUICK_SCENARIOS`` scenarios, for exploring (saved as ``eig-quick_<sha12>.json``, never
  read by ``submit``);
- ``link-check``: the recovery test (`src.rsa_open.fit.recovery_check`) of the spec's link **in
  this paradigm**: its scene space, its number of responses, its scale, simulated from a live
  theory at its posterior mean and the link at its reference values. The theory is the one with
  the most parameters unless named (`default_theory`): under the literal listener, which is flat
  over the true objects, a listener link's temperature changes nothing, so no paradigm could
  recover it (the 2026-10-21 smoke failed every choice paradigm that way);
- ``submit``: records the spec as the session's submission, once it has an ``eig`` report that
  meets the floor and a ``link-check`` report that recovers, both of this exact spec (sha256).

Every report is written to ``work/reports/<command>_<sha12>.json``. ``submit`` only records:
the harness then re-scores the spec with a seed of its own, reruns the link check, and pilots
it (`src.rsa_open.designer`); the agent's reports are never trusted as the gate.

**The call budget.** Every command is a line in ``work/tool_log.jsonl``, and a command past
``MAX_TOOL_CALLS`` is refused (PI 2026-10-21: 40 calls). The log is in the agent's own
directory; the harness counts it too and the agent's transcript records every command.
"""

from __future__ import annotations

import hashlib
import json
import sys
import time
from dataclasses import dataclass
from pathlib import Path
from typing import Annotated, Any, Dict, Optional, Union

import numpy as np
import tyro

MAX_TOOL_CALLS = 40
TOOL_LOG = "tool_log.jsonl"
SUBMISSION = "submission.json"
# Link check: NUTS settings and the replicates of the library's recovery test.
LINK_CHECK_WARMUP = 500
LINK_CHECK_SAMPLES = 500
# eig --quick: about a twentieth of the full score's draws x scenarios (2026-10-21: a full eig took
# ~6.5 min of the first designer's 114, its greedy selection most of that).
QUICK_DRAWS = 16
QUICK_SCENARIOS = 200


class ToolRefused(RuntimeError):
    """A command the tools will not run (budget spent, workspace broken, prerequisites missing)."""


@dataclass(frozen=True)
class Workspace:
    root: Path

    @property
    def context(self) -> Path:
        return self.root / "context"

    @property
    def inputs(self) -> Path:
        return self.root / "inputs"

    @property
    def work(self) -> Path:
        return self.root / "work"

    @property
    def reports(self) -> Path:
        return self.work / "reports"

    @property
    def log(self) -> Path:
        return self.work / TOOL_LOG

    @property
    def submission(self) -> Path:
        return self.work / SUBMISSION

    @property
    def timing(self) -> Path:
        return self.inputs / "timing.json"

    def timing_records(self) -> list:
        from src.rsa_open.timing import read_records

        if not self.timing.exists():
            raise ToolRefused(f"{self.root}: no inputs/timing.json (the harness writes it)")
        return read_records(self.timing)

    def check(self) -> None:
        missing = [p.name for p in (self.context, self.inputs, self.work) if not p.is_dir()]
        if missing:
            raise ToolRefused(f"{self.root} is not a designer workspace: no {missing}")

    def report_path(self, command: str, sha: str) -> Path:
        return self.reports / f"{command}_{sha[:12]}.json"

    def calls(self) -> list:
        if not self.log.exists():
            return []
        return [json.loads(line) for line in self.log.read_text().splitlines() if line.strip()]


def seed_for(sha: str, purpose: str) -> int:
    """A seed fixed by the spec and the use: the agent cannot pick a lucky one."""
    return int(hashlib.sha256(f"{purpose}:{sha}".encode()).hexdigest()[:8], 16)


def _log(ws: Workspace, command: str, spec: Path, sha: Optional[str], outcome: str) -> None:
    ws.work.mkdir(parents=True, exist_ok=True)
    with ws.log.open("a") as f:
        f.write(json.dumps({"command": command, "spec": str(spec), "sha256": sha, "outcome": outcome,
                            "time": time.time()}) + "\n")


def _write_report(ws: Workspace, command: str, sha: str, report: Dict[str, Any]) -> Path:
    ws.reports.mkdir(parents=True, exist_ok=True)
    path = ws.report_path(command, sha)
    path.write_text(json.dumps(report, indent=2))
    return path


# --------------------------------------------------------------------------- commands

def preview_units(paradigm, seed: int = 0) -> list:
    """``distinct_trials`` random units of the paradigm's scene space, for a time estimate before
    there is a design."""
    from src.rsa_open.design import describe_unit, trial_units
    from src.rsa_open.paradigm import paradigm_likelihood, scene_pool

    rng = np.random.default_rng(seed)
    scenes = scene_pool(paradigm)
    scenes = [scenes[i] for i in rng.permutation(len(scenes))[:2000]]
    if paradigm.response.type == "bet":
        units = [{"objects": [list(o) for o in s.objects], "heard": s.utterance} for s in scenes]
    else:
        units = [describe_unit(scenes, u) for u in trial_units(scenes, paradigm_likelihood(paradigm))]
    need = paradigm.design.distinct_trials
    if len(units) < need:
        raise ToolRefused(f"the scene space gives {len(units)} trial units; distinct_trials is {need}")
    return [units[i] for i in rng.choice(len(units), need, replace=False)]


def time_report(ws: Workspace, paradigm, units: list) -> Dict[str, Any]:
    """The pilot's time estimate for these units, calibrated on the workspace's timing records."""
    from src.rsa_open.pilot import TIME_TOLERANCE
    from src.rsa_open.screens import design_units, trial_lists
    from src.rsa_open.timing import estimate

    lists = trial_lists(paradigm, design_units({"design": units}), seed=0, n_lists=20)
    t = estimate(lists, ws.timing_records())
    ratio = t["estimated_minutes"] / paradigm.design.minutes
    return {"estimated_minutes": t["estimated_minutes"], "declared_minutes": paradigm.design.minutes,
            "within_tolerance": abs(ratio - 1.0) <= TIME_TOLERANCE, "calibration_basis": t["calibration_basis"]}


def validate(ws: Workspace, spec: Path) -> Dict[str, Any]:
    from src.rsa_open.design import trial_units
    from src.rsa_open.paradigm import load_paradigm, paradigm_likelihood, scene_pool

    p = load_paradigm(spec)
    scenes = scene_pool(p)
    # The EIG tool's limit on trial units, checked here so a spec eig cannot score fails at once
    # (trial_units raises past it).
    n_units = len(trial_units(scenes, paradigm_likelihood(p)))
    return {"valid": True, "sha256": p.sha256, "scenes": len(scenes), "units": n_units, "cost_usd": p.cost_usd,
            "response": p.response.type, "link": p.response.link,
            "time": time_report(ws, p, preview_units(p, seed_for(p.sha256, "preview")))}


def eig_report(ws: Workspace, spec: Path, *, n_draws: Optional[int] = None,
               n_scenarios: Optional[int] = None, seed: Optional[int] = None) -> Dict[str, Any]:
    from src.rsa_open.design import DEFAULT_DRAWS, DEFAULT_SCENARIOS, load_context, score_paradigm
    from src.rsa_open.paradigm import load_paradigm

    p = load_paradigm(spec)
    report = score_paradigm(p, load_context(ws.context), n_draws=n_draws or DEFAULT_DRAWS,
                            n_scenarios=n_scenarios or DEFAULT_SCENARIOS,
                            seed=seed_for(p.sha256, "eig") if seed is None else seed)
    report["time"] = time_report(ws, p, report["design"])
    return report


def default_theory(ctx) -> str:
    """The live theory a link check simulates from: the one with the most parameters (ties by name)."""
    return sorted(ctx.names, key=lambda n: (-len(ctx.theories[n].params), n))[0]


def link_check_report(ws: Workspace, spec: Path, *, theory: Optional[str] = None,
                      seed: Optional[int] = None, warmup: int = LINK_CHECK_WARMUP,
                      samples: int = LINK_CHECK_SAMPLES) -> Dict[str, Any]:
    from src.rsa.fit import FitSettings
    from src.rsa_open.design import load_context
    from src.rsa_open.fit import recovery_check
    from src.rsa_open.paradigm import load_paradigm, paradigm_likelihood, scene_pool

    p = load_paradigm(spec)
    ctx = load_context(ws.context)
    name = theory or default_theory(ctx)
    if name not in ctx.theories:
        raise ToolRefused(f"no live theory {name!r}; the live theories are {ctx.names}")
    link = paradigm_likelihood(p)
    truth = {**{k: float(np.mean(v)) for k, v in ctx.draws[name].items()}, **link.reference_params}
    seed = seed_for(p.sha256, "link_check") if seed is None else seed
    n_trials = p.design.n_participants * p.design.trials_per_participant
    settings = FitSettings(num_warmup=warmup, num_samples=samples, num_chains=2, seed=seed, dense_mass=True)
    report = recovery_check(ctx.root / "theories" / f"{name}.py", link, truth, n_trials=n_trials, seed=seed,
                            contexts=scene_pool(p), settings=settings)
    return {"paradigm_sha256": p.sha256, "theory": name, "truth": truth, **report}


def submit(ws: Workspace, spec: Path) -> Dict[str, Any]:
    from src.rsa_open.paradigm import load_paradigm

    p = load_paradigm(spec)
    problems = []
    eig_path, link_path = ws.report_path("eig", p.sha256), ws.report_path("link-check", p.sha256)
    if not eig_path.exists():
        problems.append("no eig report for this exact spec: run `eig` on it")
    elif not json.loads(eig_path.read_text()).get("meets_floor"):
        problems.append("its eig report is below the floor")
    if not link_path.exists():
        problems.append("no link-check report for this exact spec: run `link-check` on it")
    else:
        lc = json.loads(link_path.read_text())
        if not (lc.get("converged") and lc.get("recovered")):
            problems.append(f"its link check failed (converged={lc.get('converged')}, misses={lc.get('misses')})")
    if problems:
        raise ToolRefused("not submitted:\n" + "\n".join(f"- {x}" for x in problems))
    record = {"spec": str(Path(spec).resolve()), "sha256": p.sha256, "time": time.time()}
    ws.submission.write_text(json.dumps(record, indent=2))
    return record


# --------------------------------------------------------------------------- CLI

@dataclass
class _Common:
    workspace: Path
    """The designer workspace (the brief gives its path)."""
    spec: Path
    """The paradigm spec (a JSON file in the workspace's work/)."""


@dataclass
class Validate(_Common):
    """List every problem with a spec, or confirm it is valid."""


@dataclass
class Eig(_Common):
    """Score the paradigm's design under the live theories: bits, bits per dollar, the floor."""

    quick: bool = False
    """An approximate score (fewer draws and scenarios; minutes less): for exploring. Its report
    is saved apart, and submit needs a full eig of the spec."""


@dataclass
class LinkCheck(_Common):
    """The link's recovery test in this paradigm (several minutes: three NUTS fits)."""

    theory: Optional[str] = None
    """The live theory to simulate from (default: the first)."""


@dataclass
class Submit(_Common):
    """Submit the spec (needs a passing eig and link-check report of this exact spec)."""


Command = Union[
    Annotated[Validate, tyro.conf.subcommand("validate")],
    Annotated[Eig, tyro.conf.subcommand("eig")],
    Annotated[LinkCheck, tyro.conf.subcommand("link-check")],
    Annotated[Submit, tyro.conf.subcommand("submit")],
]
NAMES = {Validate: "validate", Eig: "eig", LinkCheck: "link-check", Submit: "submit"}


def report_name(command: str, report: Dict[str, Any]) -> str:
    """A quick eig's report is saved apart: submit reads only the full one."""
    return "eig-quick" if command == "eig" and report.get("quick") else command


def _summary(command: str, report: Dict[str, Any]) -> str:
    t = report.get("time") if command in ("validate", "eig") else None
    timing = "" if t is None else (
        f"; time: estimated {t['estimated_minutes']:.1f} min against your {t['declared_minutes']:g} "
        f"({'within' if t['within_tolerance'] else 'NOT within'} the pilot's 30%; calibrated on "
        f"{t['calibration_basis']})")
    if command == "validate":
        units = "" if report["units"] is None else f" ({report['units']} trial units)"
        return (f"valid: {report['scenes']} scenes{units}, {report['response']} via {report['link']}, "
                f"${report['cost_usd']:.2f}; sha256 {report['sha256'][:12]}{timing}")
    if command == "eig":
        line = (f"{report['joint_eig_bits']:.3f} of {report['max_bits']:.3f} bits "
                f"(p_correct {report['p_correct']:.2f}), ${report['cost_usd']:.2f}, "
                f"{report['bits_per_dollar']:.5f} bits/$")
        if report.get("quick"):
            line = "QUICK (approximate; submit needs a full eig): " + line
        if "floor_bits_per_dollar" in report:
            line += (f"; floor {report['floor_bits_per_dollar']:.5f}: "
                     f"{'MEETS' if report['meets_floor'] else 'BELOW'}")
        return line + timing
    if command == "link-check":
        return (f"link {report['link']} in this paradigm ({report['n_trials']} responses, theory "
                f"{report['theory']}): converged={report['converged']}, recovered={report['recovered']}, "
                f"misses={report['misses']}")
    return f"submitted {report['sha256'][:12]}"


def run(cmd: Any) -> Dict[str, Any]:
    """Run one command, under the budget; return its report (raises `ToolRefused` or `ParadigmInvalid`)."""
    from src.rsa_open.paradigm import ParadigmInvalid, load_paradigm

    command = NAMES[type(cmd)]
    ws = Workspace(Path(cmd.workspace))
    ws.check()
    used = len(ws.calls())
    if used >= MAX_TOOL_CALLS:
        raise ToolRefused(f"the tool budget ({MAX_TOOL_CALLS} calls) is spent: submit what you have or stop")
    try:
        sha = load_paradigm(cmd.spec).sha256
    except (ParadigmInvalid, OSError):
        sha = None
    try:
        if command == "validate":
            report = validate(ws, cmd.spec)
        elif command == "eig" and cmd.quick:
            report = eig_report(ws, cmd.spec, n_draws=QUICK_DRAWS, n_scenarios=QUICK_SCENARIOS)
            report["quick"] = True
        elif command == "eig":
            report = eig_report(ws, cmd.spec)
        elif command == "link-check":
            report = link_check_report(ws, cmd.spec, theory=cmd.theory)
        else:
            report = submit(ws, cmd.spec)
    except Exception as err:
        _log(ws, command, cmd.spec, sha, f"refused: {type(err).__name__}")
        raise
    _log(ws, command, cmd.spec, sha, "ok")
    if command in ("eig", "link-check"):
        _write_report(ws, report_name(command, report), report["paradigm_sha256"], report)
    report["calls_left"] = MAX_TOOL_CALLS - used - 1
    return report


def main(argv: Optional[list] = None) -> int:
    from src.rsa_open.paradigm import ParadigmInvalid

    cmd = tyro.cli(Command, args=argv)
    command = NAMES[type(cmd)]
    try:
        report = run(cmd)
    except (ParadigmInvalid, ToolRefused, NotImplementedError, ValueError) as err:
        print(f"{command}: {err}")
        return 1
    print(f"{command}: {_summary(command, report)} ({report['calls_left']} tool calls left)")
    if command in ("eig", "link-check"):
        path = Workspace(Path(cmd.workspace)).report_path(report_name(command, report), report["paradigm_sha256"])
        print(f"report: {path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

"""The paradigm spec the designer writes, and its validator (docs/auto_open/PLAN.md §3, §4, §8).

A paradigm is one JSON file: what the experiment asks (the charter question), its
instructions and comprehension checks, its materials (SVG or text only), the space of scenes
its trials are drawn from, the response type and the link that scores it, and the design (N,
trials, length, pay). Every trial maps onto an abstract scene, a `src.rsa.context.Context`:
referents with features and a heard message or none. Theories see only those scenes.

`load_paradigm` validates a spec and raises `ParadigmInvalid` listing **every** problem at once,
so an agent fixing a spec sees them all. It checks:
- structure and types, with unknown keys refused (a typo fails loudly);
- the design against the campaign's bounds: the closed campaign's budget per experiment
  (`BUDGET_USD`), at least `MIN_PARTICIPANTS`, at most `MAX_MINUTES` per person, and pay at the
  closed campaign's hourly rate (`MIN_HOURLY_USD`);
- the scene space: at most `MAX_OBJECTS` objects and `MAX_FEATURES` features, and at most
  `MAX_POOL` scenes (the EIG tools score every one);
- materials: every domain names enough features for the largest scene; SVG is well-formed and
  contains only drawing elements (no script, foreignObject, images, links, styles, event
  handlers, or references outside the fragment); text materials give each feature a phrase;
- content (PI 2026-10-20): no deception, no affectively charged stimuli or language, no URLs
  or email addresses;
- the response's link exists in the library (`src.rsa_open.links`) and scores its type; a
  rating gives its scale points and a slider its total points.

A paradigm's `sha256` is that of its canonical JSON, so formatting does not change it and any
content does; it is recorded with every trial collected under the paradigm.

    python -m src.rsa_open.paradigm --spec paradigm.json
    python -m src.rsa_open.paradigm --schema-out schema.json   # the JSON schema, for the designer
"""

from __future__ import annotations

import hashlib
import json
import re
import xml.etree.ElementTree as ET
from dataclasses import dataclass
from functools import cached_property
from pathlib import Path
from typing import Any, Dict, List, Literal, Optional

import tyro
from pydantic import BaseModel, ConfigDict, ValidationError

# The closed campaign's experiment: 200 people x $0.50 for 3 minutes, plus Prolific's fee of a
# third (PLAN.md, decisions of 2026-10-21: equal dollars per experiment).
PROLIFIC_FEE_MULTIPLIER = 4.0 / 3.0
BUDGET_USD = 200 * 0.50 * PROLIFIC_FEE_MULTIPLIER
MIN_HOURLY_USD = 0.50 / 3 * 60
MIN_PARTICIPANTS = 100
MAX_MINUTES = 15
MAX_OBJECTS = 6
MAX_FEATURES = 4
MAX_POOL = 6000
MAX_SVG_CHARS = 20_000
MAX_SCALE_POINTS = 11
MAX_TOTAL_POINTS = 1000
RESPONSE_TYPES = ("choice", "rating", "slider", "bet", "production", "binary_judgment")
LISTENER_TYPES = ("choice", "rating", "slider", "bet")
MESSAGE = "{message}"
PLACEHOLDER = re.compile(r"\{[^{}]*\}")
QUOTED_MESSAGE = re.compile(r"[\"'“”‘’«»]\s*\{message\}|\{message\}\s*[\"'“”‘’«»]")

SVG_NS = "http://www.w3.org/2000/svg"
SVG_ELEMENTS = {
    "svg", "g", "rect", "circle", "ellipse", "line", "polyline", "polygon", "path", "text",
    "tspan", "title", "desc", "defs", "linearGradient", "radialGradient", "stop", "clipPath", "use",
}
# A crude backstop to the PI's review of each chain's first paradigm, not a content classifier.
CHARGED = re.compile(
    r"\b(blood\w*|kill\w*|dead|death\w*|die[sd]?|dying|murder\w*|suicid\w*|abus\w*|violen\w*|"
    r"weapon\w*|guns?|knife|knives|sex\w*|nude|naked|drugs?|alcohol\w*|racis\w*|terror\w*|"
    r"tortur\w*|injur\w*|wound\w*|corpse\w*|hate\w*|disease\w*|cancer|vomit\w*|gore)\b",
    re.IGNORECASE,
)
URL = re.compile(r"https?://|www\.", re.IGNORECASE)
EMAIL = re.compile(r"[\w.+-]+@[\w-]+\.[\w.]+")
WORD = re.compile(r"^[a-z][a-z' -]{0,30}$")


class ParadigmInvalid(ValueError):
    """A paradigm spec that cannot be used; the message lists every problem."""

    def __init__(self, path: str, problems: List[str]) -> None:
        self.problems = problems
        super().__init__(f"{path}: {len(problems)} problem(s):\n" + "\n".join(f"- {p}" for p in problems))


class _Strict(BaseModel):
    model_config = ConfigDict(extra="forbid")


class Charter(_Strict):
    question: str
    """The question about pragmatic reference this paradigm asks (docs/auto_open/PLAN.md §2)."""


class ComprehensionCheck(_Strict):
    question: str
    options: List[str]
    correct: int


class Instructions(_Strict):
    welcome: str
    task: str
    comprehension_checks: List[ComprehensionCheck]


class Feature(_Strict):
    word: str
    svg: Optional[str] = None
    """An SVG fragment drawn over the domain's base, in the same 100 x 100 box (materials.kind
    'svg')."""
    phrase: Optional[str] = None
    """How the feature is written (materials.kind 'text'), e.g. 'with a garden'."""


class Domain(_Strict):
    name: str
    base: str
    """The object without features: an SVG fragment drawn in a 100 x 100 box (viewBox
    "0 0 100 100"), or a noun phrase for text."""
    features: List[Feature]


class Materials(_Strict):
    kind: Literal["svg", "text"]
    domains: List[Domain]


class SceneSpace(_Strict):
    sizes: List[List[int]]
    """[n_objects, n_features] pairs; every valid game of each size is in the pool."""
    prior_queries: bool
    """Include trials with no informative message (the listener's prior)."""
    synonyms: bool
    """Include games in which two features have the same extension."""


class Response(_Strict):
    type: Literal["choice", "rating", "slider", "bet", "production", "binary_judgment"]
    link: str
    prompt: str
    """Shown on every trial. A listener trial (choice, rating, slider, bet) and a judgment show
    the message where the prompt says ``{message}`` (required), in quotation marks the page adds;
    a production trial shows none."""
    prior_prompt: Optional[str] = None
    """A listener trial with no informative message (scene_space.prior_queries): its prompt,
    without ``{message}``. Required exactly when such trials exist."""
    scale_labels: Optional[List[str]] = None
    """rating and slider: the labels of the scale's two ends, [low, high]."""
    scale_points: Optional[int] = None
    """rating: the number of points on the scale (2-11), frozen with the paradigm."""
    total_points: Optional[int] = None
    """slider: its maximum (a 0-max slider on one referent); bet: the points split over the
    referents. 2-1000, frozen with the paradigm."""


class Design(_Strict):
    n_participants: int
    trials_per_participant: int
    distinct_trials: int
    """D, the trial units the design picks (`src.rsa_open.design`); each participant answers a
    balanced subset, so each unit gets n_participants x trials_per_participant / D responses."""
    catch_trials: int
    minutes: float
    pay_usd: float


class Content(_Strict):
    deception: bool
    affective_stimuli: bool


class Paradigm(_Strict):
    schema_version: Literal[1]
    name: str
    summary: str
    charter: Charter
    instructions: Instructions
    materials: Materials
    scene_space: SceneSpace
    response: Response
    design: Design
    content: Content

    @property
    def cost_usd(self) -> float:
        return self.design.n_participants * self.design.pay_usd * PROLIFIC_FEE_MULTIPLIER

    @cached_property
    def sha256(self) -> str:
        canonical = json.dumps(self.model_dump(mode="json"), sort_keys=True, separators=(",", ":"),
                               ensure_ascii=False)
        return hashlib.sha256(canonical.encode("utf-8")).hexdigest()

    def max_features(self) -> int:
        return max(f for _, f in self.scene_space.sizes)


def _svg_problems(fragment: str, where: str) -> List[str]:
    if len(fragment) > MAX_SVG_CHARS:
        return [f"{where}: SVG is {len(fragment)} characters, over the {MAX_SVG_CHARS} limit"]
    if re.search(r"<!(DOCTYPE|ENTITY)", fragment, re.IGNORECASE):
        return [f"{where}: SVG may not declare a DOCTYPE or entities"]
    try:
        root = ET.fromstring(f'<svg xmlns="{SVG_NS}">{fragment}</svg>')
    except ET.ParseError as err:
        return [f"{where}: SVG is not well-formed ({err})"]
    problems = []
    for el in root.iter():
        tag = el.tag.split("}")[-1]
        if tag not in SVG_ELEMENTS:
            problems.append(f"{where}: SVG element <{tag}> is not allowed (drawing elements only)")
        for attr, value in el.attrib.items():
            name = attr.split("}")[-1]
            if name.lower().startswith("on"):
                problems.append(f"{where}: SVG event handler attribute {name} is not allowed")
            if name == "href" and not value.startswith("#"):
                problems.append(f"{where}: SVG href {value!r} points outside the fragment")
            if "url(" in value.replace(" ", "") and not re.fullmatch(r"\s*url\(#[\w-]+\)\s*", value):
                problems.append(f"{where}: SVG attribute {name} references {value!r} outside the fragment")
    return problems


def _texts(p: Paradigm) -> List[tuple]:
    """Every piece of designer-written text a participant can see, with where it is."""
    out = [("name", p.name), ("summary", p.summary), ("charter.question", p.charter.question),
           ("instructions.welcome", p.instructions.welcome), ("instructions.task", p.instructions.task),
           ("response.prompt", p.response.prompt)]
    if p.response.prior_prompt:
        out.append(("response.prior_prompt", p.response.prior_prompt))
    out += [(f"response.scale_labels[{i}]", x) for i, x in enumerate(p.response.scale_labels or [])]
    for i, check in enumerate(p.instructions.comprehension_checks):
        out.append((f"instructions.comprehension_checks[{i}].question", check.question))
        out += [(f"instructions.comprehension_checks[{i}].options[{j}]", o) for j, o in enumerate(check.options)]
    for d, domain in enumerate(p.materials.domains):
        out.append((f"materials.domains[{d}].name", domain.name))
        if p.materials.kind == "text":
            out.append((f"materials.domains[{d}].base", domain.base))
        for f, feature in enumerate(domain.features):
            out.append((f"materials.domains[{d}].features[{f}].word", feature.word))
            if feature.phrase:
                out.append((f"materials.domains[{d}].features[{f}].phrase", feature.phrase))
    return out


def _svg_texts(p: Paradigm) -> List[tuple]:
    """The text drawn inside SVG fragments (<text>, <tspan>, <title>)."""
    out = []
    if p.materials.kind != "svg":
        return out
    for d, domain in enumerate(p.materials.domains):
        fragments = [(f"materials.domains[{d}].base", domain.base)] + [
            (f"materials.domains[{d}].features[{f}].svg", feat.svg or "") for f, feat in enumerate(domain.features)]
        for where, fragment in fragments:
            try:
                root = ET.fromstring(f'<svg xmlns="{SVG_NS}">{fragment}</svg>')
            except ET.ParseError:
                continue
            text = " ".join(t for t in root.itertext() if t.strip())
            if text:
                out.append((where, text))
    return out


def _problems(p: Paradigm) -> List[str]:
    from src.rsa_open.links import LINKS

    problems: List[str] = []
    d = p.design
    if d.n_participants < MIN_PARTICIPANTS:
        problems.append(f"design.n_participants {d.n_participants} is below the minimum of {MIN_PARTICIPANTS}")
    if not 0 < d.minutes <= MAX_MINUTES:
        problems.append(f"design.minutes {d.minutes:g} is outside (0, {MAX_MINUTES}], the maximum per person")
    if d.minutes > 0 and d.pay_usd / d.minutes * 60 < MIN_HOURLY_USD - 1e-9:
        problems.append(f"design.pay_usd ${d.pay_usd:.2f} for {d.minutes:g} minutes is "
                        f"${d.pay_usd / d.minutes * 60:.2f} per hour, below ${MIN_HOURLY_USD:.2f} per hour")
    if p.cost_usd > BUDGET_USD + 0.01:
        problems.append(f"design costs ${p.cost_usd:.2f} (n_participants x pay_usd x "
                        f"{PROLIFIC_FEE_MULTIPLIER:.4g}), over the ${BUDGET_USD:.2f} budget per experiment")
    if d.trials_per_participant < 1:
        problems.append("design.trials_per_participant must be at least 1")
    if d.distinct_trials < max(d.trials_per_participant, 1):
        problems.append(f"design.distinct_trials {d.distinct_trials} must be at least trials_per_participant "
                        f"({d.trials_per_participant})")
    elif d.n_participants * d.trials_per_participant < d.distinct_trials:
        problems.append("design.distinct_trials is more than the responses collected "
                        "(n_participants x trials_per_participant): some units would get none")
    if d.catch_trials < 1:
        problems.append("design.catch_trials must be at least 1 (attention is checked in every paradigm)")

    sizes_ok = True
    if not p.scene_space.sizes:
        problems.append("scene_space.sizes is empty")
        sizes_ok = False
    for size in p.scene_space.sizes:
        if len(size) != 2:
            problems.append(f"scene_space.sizes entry {size} must be [n_objects, n_features]")
            sizes_ok = False
            continue
        n_obj, n_feat = size
        if not 2 <= n_obj <= MAX_OBJECTS:
            problems.append(f"scene_space.sizes {size}: between 2 and {MAX_OBJECTS} objects")
            sizes_ok = False
        if not 2 <= n_feat <= MAX_FEATURES:
            problems.append(f"scene_space.sizes {size}: between 2 and {MAX_FEATURES} features")
            sizes_ok = False
    if sizes_ok:
        n_pool = len(scene_pool(p))
        if n_pool > MAX_POOL:
            problems.append(f"scene_space gives {n_pool} scenes, over the {MAX_POOL} the EIG tools score")
        elif n_pool == 0:
            problems.append("scene_space gives no scenes")

    kind = p.materials.kind
    if not p.materials.domains:
        problems.append("materials.domains is empty")
    for i, domain in enumerate(p.materials.domains):
        where = f"materials.domains[{i}] ({domain.name})"
        if sizes_ok and len(domain.features) < p.max_features():
            problems.append(f"{where} names {len(domain.features)} features; scenes need {p.max_features()} features")
        words = [f.word for f in domain.features]
        if len(set(words)) != len(words):
            problems.append(f"{where}: feature words must differ ({words})")
        for j, feature in enumerate(domain.features):
            fwhere = f"{where}.features[{j}] ({feature.word})"
            if not WORD.match(feature.word):
                problems.append(f"{fwhere}: a word is 1-30 lowercase letters, spaces, hyphens or apostrophes")
            if kind == "svg":
                if not feature.svg:
                    problems.append(f"{fwhere}: svg materials need an svg fragment per feature")
                else:
                    problems += _svg_problems(feature.svg, fwhere)
            elif not feature.phrase:
                problems.append(f"{fwhere}: text materials need a phrase per feature")
        if kind == "svg":
            problems += _svg_problems(domain.base, f"{where}.base")

    for where, text in _texts(p) + _svg_texts(p):
        if CHARGED.search(text):
            problems.append(f"{where}: affectively charged language ({CHARGED.search(text).group(0)!r})")
        if URL.search(text):
            problems.append(f"{where}: no URLs")
        if EMAIL.search(text):
            problems.append(f"{where}: no email addresses")

    if p.content.deception:
        problems.append("content.deception: deception is not allowed (PI 2026-10-20)")
    if p.content.affective_stimuli:
        problems.append("content.affective_stimuli: affectively charged stimuli are not allowed (PI 2026-10-20)")

    link = LINKS.get(p.response.link)
    if link is None:
        problems.append(f"response.link {p.response.link!r} is not in the link library ({', '.join(sorted(LINKS))})")
    elif link.response_type != p.response.type:
        problems.append(f"response.link {link.name!r} scores {link.response_type!r} responses, not {p.response.type!r}")
    if not p.response.prompt.strip():
        problems.append("response.prompt is empty")
    r = p.response
    listener = r.type in LISTENER_TYPES
    for field in ("prompt", "prior_prompt"):
        text = getattr(r, field) or ""
        other = sorted(set(PLACEHOLDER.findall(text)) - {MESSAGE})
        if other:
            problems.append(f"response.{field}: unknown placeholders {other}; the only one is {MESSAGE}")
    wants_message = listener or r.type == "binary_judgment"
    if wants_message and r.prompt.count(MESSAGE) != 1:
        problems.append(f"response.prompt must show the message once, where it says {MESSAGE}")
    if QUOTED_MESSAGE.search(r.prompt):
        problems.append(f"response.prompt: no quotation marks around {MESSAGE}: the page shows the word in "
                        f"quotation marks itself")
    if not wants_message and MESSAGE in r.prompt:
        problems.append(f"response.prompt: a {r.type} trial has no message to show ({MESSAGE})")
    if listener and p.scene_space.prior_queries:
        if not (r.prior_prompt or "").strip():
            problems.append("response.prior_prompt is required: scene_space.prior_queries gives trials with "
                            "no informative message")
        elif MESSAGE in r.prior_prompt:
            problems.append(f"response.prior_prompt: those trials have no message to show ({MESSAGE})")
    elif r.prior_prompt is not None:
        problems.append("response.prior_prompt applies only to listener responses with scene_space.prior_queries")
    if r.type in ("rating", "slider"):
        if r.scale_labels is None or len(r.scale_labels) != 2 or not all(x.strip() for x in r.scale_labels):
            problems.append(f"response.scale_labels must be [low, high] for a {r.type} response")
    elif r.scale_labels is not None:
        problems.append("response.scale_labels applies only to rating and slider responses")
    if r.type == "rating":
        if r.scale_points is None or not 2 <= r.scale_points <= MAX_SCALE_POINTS:
            problems.append(f"response.scale_points must be 2-{MAX_SCALE_POINTS} for a rating response")
    elif r.scale_points is not None:
        problems.append("response.scale_points applies only to rating responses")
    if r.type in ("slider", "bet"):
        if r.total_points is None or not 2 <= r.total_points <= MAX_TOTAL_POINTS:
            problems.append(f"response.total_points must be 2-{MAX_TOTAL_POINTS} for a {r.type} response")
    elif r.total_points is not None:
        problems.append("response.total_points applies only to slider and bet responses")

    checks = p.instructions.comprehension_checks
    if not checks:
        problems.append("instructions.comprehension_checks: at least one is required")
    for i, check in enumerate(checks):
        if len(check.options) < 2:
            problems.append(f"instructions.comprehension_checks[{i}] needs at least two options")
        elif not 0 <= check.correct < len(check.options):
            problems.append(f"instructions.comprehension_checks[{i}].correct is not an option index")
    for field in ("welcome", "task"):
        if not getattr(p.instructions, field).strip():
            problems.append(f"instructions.{field} is empty")
    if len(p.charter.question.strip()) < 15:
        problems.append("charter.question must state the question about pragmatic reference the paradigm asks")
    return problems


def parse_paradigm(spec: Dict[str, Any], where: str = "paradigm") -> Paradigm:
    try:
        paradigm = Paradigm.model_validate(spec)
    except ValidationError as err:
        raise ParadigmInvalid(where, [
            f"{'.'.join(str(x) for x in e['loc']) or '(top level)'}: {e['msg']}" for e in err.errors()
        ]) from None
    problems = _problems(paradigm)
    if problems:
        raise ParadigmInvalid(where, problems)
    return paradigm


def load_paradigm(path: Path) -> Paradigm:
    path = Path(path)
    try:
        spec = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as err:
        raise ParadigmInvalid(str(path), [f"not valid JSON ({err})"]) from None
    return parse_paradigm(spec, str(path))


def scene_pool(paradigm: Paradigm) -> list:
    """The abstract scenes the paradigm's trials can show (`src.rsa.context.Context`)."""
    from src.rsa.design_space import context_pool

    return context_pool([tuple(s) for s in paradigm.scene_space.sizes],
                        include_prior_queries=paradigm.scene_space.prior_queries,
                        synonyms=paradigm.scene_space.synonyms)


def paradigm_likelihood(paradigm: Paradigm):
    """The paradigm's link likelihood, with its frozen options (`src.rsa_open.links`)."""
    from src.rsa_open.links import likelihood

    return likelihood(paradigm.response.link, scale_points=paradigm.response.scale_points,
                      total_points=paradigm.response.total_points)


def main_schema(out: Path) -> dict:
    schema = Paradigm.model_json_schema()
    Path(out).write_text(json.dumps(schema, indent=2))
    return schema


@dataclass
class Args:
    spec: Optional[Path] = None
    """A paradigm spec to validate."""
    schema_out: Optional[Path] = None
    """Write the spec's JSON schema here."""


def main(args: Args) -> None:
    if args.spec is None and args.schema_out is None:
        raise SystemExit("give --spec and/or --schema-out")
    if args.schema_out is not None:
        main_schema(args.schema_out)
        print(f"schema -> {args.schema_out}")
    if args.spec is not None:
        p = load_paradigm(args.spec)
        print(f"{args.spec}: valid. {len(scene_pool(p))} scenes; {p.response.type} via link {p.response.link!r}; "
              f"N={p.design.n_participants}, {p.design.minutes:g} min, ${p.cost_usd:.2f}; sha256 {p.sha256}")


if __name__ == "__main__":
    main(tyro.cli(Args))

"""A frozen paradigm and its design -> what each participant sees, and the data back
(docs/auto_open/PLAN.md §4: the page, the pilot and the data all come from these lists).

The plan had an implementer agent write each paradigm's jsPsych page. Every spec uses one of
six response widgets with SVG or text materials, so the page is instead one generic, tested
player (`src/rsa_open/page.html`, `src.rsa_open.page`) of the lists built here, and the
simulated pilot (`src.rsa_open.pilot`) reads the same lists: what LLM participants see is
what people see.

**Trial lists** (`trial_lists`): one list per participant, a pure function of (paradigm, design,
seed, list index), so randomisation happens here, not in the page:
- **test trials**: the design's units (`src.rsa_open.design`: a scene and, by response type, a
  probed object, a target, a judged message). List ``p`` takes ``trials_per_participant``
  consecutive units of one shuffled order of the design, starting at ``p x trials``, so every
  unit is answered equally often (to within one) across lists; the list shuffles them.
- **catch trials** (``design.catch_trials``) at random positions, and one **practice** trial
  first: a scene with a word true of exactly one object (the closed campaign's
  `_catch_spec`), each with what passing means (`CATCH_RULES`). A judgment's catch trials
  alternate that word for its object (answer yes) and for another object, of which it is false
  (answer no), so answering one way fails.
- **domains** rotate (least used first, not the previous trial's when another can serve), and
  each trial maps the scene's abstract features onto distinct features of its domain at random;
  the objects' screen order is a random permutation (``display_order[p]`` is the scene's object
  at screen position ``p``).
- **rendering**: each object is drawn as an SVG (the domain's base, then its features' fragments,
  in a 100 x 100 box) or written as a phrase ("a house with a garden and with a pool"); the
  prompt shows the message as the speaker's word. A production trial's buttons are the scene's
  words in a random order; a slider or rating names its ends.

**Data**: the page records, per trial, the trial's scene, its list fields and ``response``
in the link's form (`src.rsa_open.links.LinkLikelihood.encode`), with objects and messages as
scene indices, never screen positions. `scenes_and_responses` turns test rows back into scenes
(the design pool's abstract feature names, as the theories saw in design) and responses, and
`catch_passed` scores a catch trial.
"""

from __future__ import annotations

import hashlib
import html
import json
from typing import Any, Dict, List, Mapping, Optional, Sequence, Tuple

import numpy as np

from src.rsa.context import Context
from src.rsa.design_space import feature_names as abstract_feature_names

SCHEMA = "rsa_open_lists/1"
PRACTICE_SHAPE = (3, 2)
SUBSET_STREAM = 2**31 - 1
UNIT_FIELDS = ("probe", "target", "utterance")
PHASES = ("practice", "test", "catch")


# --------------------------------------------------------------------------- the design

def design_units(report: Mapping[str, Any]) -> List[Dict[str, Any]]:
    """The design's units from an EIG report (`src.rsa_open.design.score_paradigm`)."""
    units = []
    for i, u in enumerate(report["design"]):
        unit = {"objects": [list(map(int, row)) for row in u["objects"]], "heard": u["heard"],
                **{k: int(u[k]) for k in UNIT_FIELDS if k in u}}
        scene_of(unit)  # a unit that is not a valid scene fails here
        units.append(unit)
    if not units:
        raise ValueError("the design has no units")
    return units


def design_sha256(units: Sequence[Mapping[str, Any]]) -> str:
    blob = json.dumps(list(units), sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(blob.encode()).hexdigest()


def scene_of(trial: Mapping[str, Any]) -> Context:
    """The abstract scene of a unit or trial: the design pool's feature names."""
    objects = tuple(tuple(int(v) for v in row) for row in trial["objects"])
    return Context(objects=objects, feature_names=abstract_feature_names(len(objects[0])),
                   utterance=trial["heard"])


# --------------------------------------------------------------------------- catch trials

def _catch(shape: Tuple[int, int], rng: np.random.Generator, response_type: str, k: int,
           options: Mapping[str, int]) -> Dict[str, Any]:
    """An unambiguous trial and what passing it means, for the ``k``-th catch trial."""
    from src.rsa.experiment.design import _catch_spec

    spec, target = _catch_spec(shape, rng)
    word = spec.utterance
    objects = [list(r) for r in spec.objects]
    trial: Dict[str, Any] = {"objects": objects, "heard": word}
    if response_type == "choice":
        trial["expect"] = {"choice": target}
    elif response_type == "rating":
        points = options["scale_points"]
        trial.update(probe=target, expect={"min_rating": (points + 1) // 2 + 1})
    elif response_type == "slider":
        top = options["total_points"]
        trial.update(probe=target, expect={"min_value": top // 2 + 1})
    elif response_type == "bet":
        top = options["total_points"]
        trial["expect"] = {"object": target, "min_points": top // 2 + 1}
    elif response_type == "production":
        true_words = [f for f, v in enumerate(spec.objects[target]) if v]
        trial.update(target=target, expect={"utterance_in": true_words})
    elif response_type == "binary_judgment":
        if k % 2 == 1:  # the word is false of every other object
            others = [i for i in range(len(objects)) if i != target]
            trial.update(target=others[int(rng.integers(len(others)))], utterance=word, expect={"answer": False})
        else:
            trial.update(target=target, utterance=word, expect={"answer": True})
    else:
        raise KeyError(response_type)
    return trial


def catch_passed(row: Mapping[str, Any]) -> bool:
    """Whether a catch or practice trial's response meets its rule."""
    e, r = row["expect"], row["response"]
    if "choice" in e:
        return r["choice"] == e["choice"]
    if "min_rating" in e:
        return r["rating"] >= e["min_rating"]
    if "min_value" in e:
        return r["value"] >= e["min_value"]
    if "min_points" in e:
        return r["points"][e["object"]] >= e["min_points"]
    if "utterance_in" in e:
        return r["utterance"] in e["utterance_in"]
    if "answer" in e:
        return r["answer"] is e["answer"]
    raise KeyError(f"unknown catch rule {e}")


CATCH_RULES = {
    "choice": "click the one object the word is true of",
    "rating": "rate that object above the scale's middle",
    "slider": "put the slider above its middle for that object",
    "bet": "give that object more than half the points",
    "production": "pick a word that is true of the marked object",
    "binary_judgment": "answer yes for the word true of only the marked object, no when it is false of it",
}


# --------------------------------------------------------------------------- rendering

def _object_html(paradigm, domain, feats: Sequence[int], label: str) -> str:
    if paradigm.materials.kind == "svg":
        parts = [domain.base] + [domain.features[f].svg for f in feats]
        return (f'<svg class="ro-svg" viewBox="0 0 100 100" role="img" aria-label="{html.escape(label)}" '
                f'xmlns="http://www.w3.org/2000/svg">{"".join(parts)}</svg>')
    return f'<span class="ro-text">{html.escape(label)}</span>'


def _object_label(paradigm, domain, feats: Sequence[int]) -> str:
    """The object in words: a text material's phrase, an SVG's accessible name."""
    if paradigm.materials.kind == "text":
        phrases = [domain.features[f].phrase for f in feats]
        return " ".join([domain.base, " and ".join(phrases)]).strip()
    words = [domain.features[f].word for f in feats]
    return f"a {domain.name} item" + (f" with {', '.join(words)}" if words else " with nothing extra")


def _word_html(word: str) -> str:
    return f'<span class="ro-word">“{html.escape(word)}”</span>'


def _prompt_html(paradigm, trial: Mapping[str, Any], words: Sequence[str]) -> str:
    r = paradigm.response
    if r.type == "production":
        text = html.escape(r.prompt)
    elif r.type == "binary_judgment":
        text = html.escape(r.prompt).replace(html.escape("{message}"), _word_html(words[trial["utterance"]]))
    elif trial["heard"] is None:
        text = html.escape(r.prior_prompt)
    else:
        text = html.escape(r.prompt).replace(html.escape("{message}"), _word_html(words[trial["heard"]]))
    return f'<p class="ro-prompt">{text}</p>'


def _widget(paradigm, trial: Mapping[str, Any], position_of: Mapping[int, int], words: Sequence[str],
            rng: np.random.Generator) -> Dict[str, Any]:
    r = paradigm.response
    kind = r.type
    w: Dict[str, Any] = {"type": kind}
    if kind in ("rating", "slider"):
        w.update(marked=position_of[trial["probe"]], labels=list(r.scale_labels))
        w["points" if kind == "rating" else "max"] = r.scale_points if kind == "rating" else r.total_points
    elif kind == "bet":
        w["total"] = r.total_points
    elif kind == "production":
        n_feat = len(trial["objects"][0])
        order = [int(f) for f in rng.permutation(n_feat)]
        w.update(marked=position_of[trial["target"]],
                 options=[{"label": words[f], "utterance": f} for f in order])
    elif kind == "binary_judgment":
        w.update(marked=position_of[trial["target"]], options=["Yes", "No"])
    return w


def _rotate_domain(paradigm, n_features: int, counts: List[int], previous: Optional[int]) -> int:
    eligible = [i for i, d in enumerate(paradigm.materials.domains) if len(d.features) >= n_features]
    if not eligible:
        raise ValueError(f"no domain has {n_features} features")
    if previous in eligible and len(eligible) > 1:
        eligible.remove(previous)
    return min(eligible, key=lambda i: (counts[i], i))


def _concrete(paradigm, trial: Dict[str, Any], rng: np.random.Generator, counts: List[int],
              previous: Optional[int]) -> Dict[str, Any]:
    n_obj, n_feat = len(trial["objects"]), len(trial["objects"][0])
    d = _rotate_domain(paradigm, n_feat, counts, previous)
    counts[d] += 1
    domain = paradigm.materials.domains[d]
    feature_map = [int(f) for f in rng.permutation(len(domain.features))[:n_feat]]
    words = [domain.features[f].word for f in feature_map]
    display_order = [int(i) for i in rng.permutation(n_obj)]
    position_of = {obj: p for p, obj in enumerate(display_order)}
    items, labels = [], []
    for obj in display_order:
        feats = [feature_map[j] for j, v in enumerate(trial["objects"][obj]) if v]
        label = _object_label(paradigm, domain, feats)
        labels.append(label)
        items.append(_object_html(paradigm, domain, feats, label))
    return {**trial, "domain": d, "domain_name": domain.name, "feature_map": feature_map, "words": words,
            "display_order": display_order, "items_html": items, "item_labels": labels,
            "prompt_html": _prompt_html(paradigm, trial, words),
            "widget": _widget(paradigm, trial, position_of, words, rng)}


# --------------------------------------------------------------------------- lists

def _options(paradigm) -> Dict[str, int]:
    r = paradigm.response
    return {k: v for k, v in (("scale_points", r.scale_points), ("total_points", r.total_points)) if v is not None}


def _abstract_test_trial(paradigm, unit: Mapping[str, Any], rng: np.random.Generator) -> Dict[str, Any]:
    trial = {"objects": unit["objects"], "heard": unit["heard"], **{k: unit[k] for k in UNIT_FIELDS if k in unit}}
    missing = [k for k in _needed_fields(paradigm.response.type) if k not in trial]
    if missing:
        raise ValueError(f"a {paradigm.response.type} design unit needs {missing}: {dict(unit)}")
    return trial


def _needed_fields(response_type: str) -> Tuple[str, ...]:
    return {"rating": ("probe",), "slider": ("probe",), "production": ("target",),
            "binary_judgment": ("target", "utterance")}.get(response_type, ())


def trial_list(paradigm, units: Sequence[Mapping[str, Any]], seed: int, index: int) -> Dict[str, Any]:
    """List ``index``: one participant's practice, test and catch trials, fully concrete."""
    d = paradigm.design
    order = np.random.default_rng([seed, SUBSET_STREAM]).permutation(len(units))
    T = d.trials_per_participant
    chosen = [int(order[(index * T + k) % len(units)]) for k in range(T)]
    rng = np.random.default_rng([seed, index])
    rng.shuffle(chosen)
    kind = paradigm.response.type
    options = _options(paradigm)
    tests = [{"phase": "test", "unit": u, **_abstract_test_trial(paradigm, units[u], rng)} for u in chosen]
    shapes = [(len(t["objects"]), len(t["objects"][0])) for t in tests]
    catches = [{"phase": "catch", "unit": None,
                **_catch(shapes[int(rng.integers(len(shapes)))], rng, kind, k, options)}
               for k in range(d.catch_trials)]
    sequence = list(tests)
    for c in catches:
        sequence.insert(int(rng.integers(len(sequence) + 1)), c)
    practice = {"phase": "practice", "unit": None, **_catch(PRACTICE_SHAPE, rng, kind, 0, options)}
    counts = [0] * len(paradigm.materials.domains)
    out, previous = [], None
    for i, trial in enumerate([practice] + sequence):
        concrete = _concrete(paradigm, trial, rng, counts, previous)
        previous = concrete["domain"]
        concrete["trial_number"] = i
        out.append(concrete)
    return {"list_index": index, "seed": [seed, index], "trials": out}


def trial_lists(paradigm, units: Sequence[Mapping[str, Any]], seed: int,
                n_lists: Optional[int] = None) -> Dict[str, Any]:
    """Every participant's list (``n_participants`` by default), with the intro screens."""
    n = paradigm.design.n_participants if n_lists is None else n_lists
    if len(units) != paradigm.design.distinct_trials:
        raise ValueError(f"the design has {len(units)} units; the paradigm says distinct_trials = "
                         f"{paradigm.design.distinct_trials}")
    ins = paradigm.instructions
    return {
        "schema": SCHEMA, "paradigm_sha256": paradigm.sha256, "paradigm_name": paradigm.name,
        "design_sha256": design_sha256(units), "seed": seed, "response_type": paradigm.response.type,
        "minutes": paradigm.design.minutes, "materials_kind": paradigm.materials.kind,
        "intro": {"welcome": ins.welcome, "task": ins.task,
                  "checks": [c.model_dump() for c in ins.comprehension_checks]},
        "lists": [trial_list(paradigm, units, seed, i) for i in range(n)],
    }


# --------------------------------------------------------------------------- data back

def scenes_and_responses(rows: Sequence[Mapping[str, Any]]) -> Tuple[List[Context], List[dict]]:
    """The test trials' scenes and responses, for `src.rsa_open.fit.OpenData.build`."""
    tests = [r for r in rows if r.get("phase") == "test"]
    return [scene_of(r) for r in tests], [dict(r["response"]) for r in tests]


def page_rows(data: Sequence[Mapping[str, Any]]) -> List[Dict[str, Any]]:
    """The trial rows of one participant's jsPsych data (the page's ``task == 'rsa_open_trial'``)."""
    rows = [dict(r) for r in data if r.get("task") == "rsa_open_trial"]
    for r in rows:
        if r.get("phase") not in PHASES:
            raise ValueError(f"trial {r.get('trial_number')}: unknown phase {r.get('phase')!r}")
        if not isinstance(r.get("response"), dict):
            raise ValueError(f"trial {r.get('trial_number')}: no response recorded")
    return rows

